import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { FiMenu, FiX, FiSun, FiMoon, FiUser, FiLogOut, FiBook, FiInfo, FiHome, FiMail } from 'react-icons/fi';
import { motion, AnimatePresence } from 'framer-motion';

const Navbar = () => {
  const { currentUser, isAuthenticated, logout, isAdmin, isTeacher, isStudent } = useAuth();
  const { darkMode, toggleDarkMode } = useTheme();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const navigate = useNavigate();

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleProfile = () => {
    setIsProfileOpen(!isProfileOpen);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  // Define dashboard link based on user role
  const getDashboardLink = () => {
    if (isAdmin) return '/dashboard/admin';
    if (isTeacher) return '/dashboard/teacher';
    if (isStudent) return '/dashboard/student';
    return '/dashboard';
  };

  return (
    <motion.nav 
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.5 }}
      className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 shadow-md sticky top-0 z-50"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex">
            <div className="flex-shrink-0 flex items-center">
              <Link to="/" className="text-2xl font-title font-bold gradient-text hover-lift">
                منصة التعليم العربية
              </Link>
            </div>
            
            {/* Desktop Menu */}
            <div className="hidden sm:mr-6 sm:flex sm:items-center sm:space-x-4 sm:space-x-reverse">
              <NavLink to="/" icon={<FiHome />}>الرئيسية</NavLink>
              <NavLink to="/courses" icon={<FiBook />}>الدورات</NavLink>
              <NavLink to="/about" icon={<FiInfo />}>من نحن</NavLink>
              <NavLink to="/contact" icon={<FiMail />}>اتصل بنا</NavLink>
            </div>
          </div>
          
          <div className="flex items-center">
            {/* Theme Toggle */}
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={toggleDarkMode}
              className="p-2 rounded-full text-gray-500 dark:text-gray-400 hover:text-primary-600 dark:hover:text-primary-400 focus:outline-none transition-colors duration-300"
              aria-label="Toggle dark mode"
            >
              {darkMode ? 
                <FiSun className="h-5 w-5 text-warning-400" /> : 
                <FiMoon className="h-5 w-5 text-secondary-600" />
              }
            </motion.button>
            
            {/* Auth Buttons */}
            <div className="hidden sm:mr-4 sm:flex">
              {isAuthenticated ? (
                <div className="relative">
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    onClick={toggleProfile}
                    className="flex items-center space-x-2 space-x-reverse bg-primary-50 dark:bg-gray-700 p-2 rounded-lg focus:outline-none border border-primary-200 dark:border-gray-600 transition-all duration-300"
                  >
                    <span className="text-sm font-medium text-gray-900 dark:text-white">{currentUser?.name}</span>
                    <div className="h-8 w-8 rounded-full bg-primary-200 dark:bg-primary-900 flex items-center justify-center text-primary-700 dark:text-primary-300">
                      <FiUser className="h-5 w-5" />
                    </div>
                  </motion.button>
                  
                  <AnimatePresence>
                    {isProfileOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: -10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: -10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute left-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-lg shadow-lg py-1 z-10 border border-gray-200 dark:border-gray-700"
                      >
                        <Link
                          to={getDashboardLink()}
                          className="block px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-primary-50 dark:hover:bg-gray-700 w-full text-right transition-colors duration-300"
                        >
                          لوحة التحكم
                        </Link>
                        <button
                          onClick={handleLogout}
                          className="flex items-center justify-between px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-600 dark:hover:text-red-400 w-full transition-colors duration-300"
                        >
                          <FiLogOut className="h-4 w-4" />
                          <span>تسجيل الخروج</span>
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ) : (
                <div className="flex space-x-2 space-x-reverse">
                  <Link to="/login" className="btn-outline">
                    تسجيل الدخول
                  </Link>
                  <Link to="/register/student" className="btn-primary">
                    التسجيل
                  </Link>
                </div>
              )}
            </div>
            
            {/* Mobile Menu Button */}
            <div className="flex sm:hidden">
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={toggleMenu}
                className="inline-flex items-center justify-center p-2 rounded-lg text-gray-500 dark:text-gray-400 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-gray-100 dark:hover:bg-gray-700 focus:outline-none transition-all duration-300"
                aria-expanded="false"
              >
                {isMenuOpen ? <FiX className="h-6 w-6" /> : <FiMenu className="h-6 w-6" />}
              </motion.button>
            </div>
          </div>
        </div>
      </div>
      
      {/* Mobile Menu */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
            className="sm:hidden border-t border-gray-200 dark:border-gray-700"
          >
            <div className="px-2 pt-2 pb-3 space-y-1">
              <MobileNavLink to="/" icon={<FiHome />}>الرئيسية</MobileNavLink>
              <MobileNavLink to="/courses" icon={<FiBook />}>الدورات</MobileNavLink>
              <MobileNavLink to="/about" icon={<FiInfo />}>من نحن</MobileNavLink>
              <MobileNavLink to="/contact" icon={<FiMail />}>اتصل بنا</MobileNavLink>
              
              {/* Mobile Auth Links */}
              {isAuthenticated ? (
                <>
                  <MobileNavLink
                    to={getDashboardLink()}
                    icon={<FiUser />}
                  >
                    لوحة التحكم
                  </MobileNavLink>
                  <button
                    onClick={handleLogout}
                    className="w-full text-right px-3 py-2 rounded-md flex items-center space-x-2 space-x-reverse text-base font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors duration-300"
                  >
                    <FiLogOut className="h-5 w-5" />
                    <span>تسجيل الخروج</span>
                  </button>
                </>
              ) : (
                <div className="flex flex-col space-y-2 pt-2">
                  <Link to="/login" className="btn-outline w-full text-center">
                    تسجيل الدخول
                  </Link>
                  <Link to="/register/student" className="btn-primary w-full text-center">
                    التسجيل
                  </Link>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
};

// Desktop Navigation Link Component
const NavLink = ({ to, children, icon }) => {
  return (
    <Link 
      to={to} 
      className="px-3 py-2 rounded-lg text-sm font-medium text-gray-800 dark:text-gray-200 hover:bg-primary-50 dark:hover:bg-primary-900/30 hover:text-primary-700 dark:hover:text-primary-300 flex items-center space-x-1 space-x-reverse transition-colors duration-300"
    >
      {icon && <span className="text-primary-600 dark:text-primary-400">{icon}</span>}
      <span>{children}</span>
    </Link>
  );
};

// Mobile Navigation Link Component
const MobileNavLink = ({ to, children, icon }) => {
  return (
    <Link 
      to={to} 
      className="block px-3 py-2 rounded-lg text-base font-medium text-gray-900 dark:text-white hover:bg-primary-50 dark:hover:bg-primary-900/30 hover:text-primary-700 dark:hover:text-primary-300 flex items-center space-x-2 space-x-reverse transition-colors duration-300"
    >
      {icon && <span className="text-primary-600 dark:text-primary-400">{icon}</span>}
      <span>{children}</span>
    </Link>
  );
};

export default Navbar;
